James: People have always been critical of the art of their own time. They forget all but the greatest art from past eras. Since inferior contemporary artworks have not yet been forgotten, people today mistakenly think that contemporary art is generally inferior to earlier art.$batch07$ AND q.prompt=$batch07$On the basis of their statements, Rachel and James are committed to disagreeing with each other about whether$batch07$ AND q.correct_choice=$batch07$A$batch07$) THEN RAISE EXCEPTION 'Question changed: PT118-S1-Q10'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT118-S1-Q10$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S1-Q10'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT118-S1-Q10$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Rachel's Position$batch07$, $batch07$Freedom from old constraints has caused a decline in the quality of art. Great art needs outside boundaries to struggle against.$batch07$), (1, $batch07$James's Position$batch07$, $batch07$People only think contemporary art is worse because they have forgotten the bad art of the past and haven't yet forgotten today's. They are mistaken.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Rachel says art has declined, which means contemporary art is worse than earlier art. James says the belief that contemporary art is generally inferior is a mistake. James never discusses Rachel's reason (constraints). James goes after Rachel's conclusion.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether contemporary art is actually worse than earlier art.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT118-S1-Q10$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Rachel: freedom "has caused a decline in the quality of art". James: people "mistakenly think that contemporary art is generally inferior to earlier art". Worse versus not worse.$batch07$), ($batch07$B$batch07$, $batch07$This is the most popular wrong answer. Rachel does say today's artists are free of their predecessors' constraints, so Rachel would deny B. But James says nothing about constraints, so we can't place James.$batch07$), ($batch07$C$batch07$, $batch07$Rachel says this almost word for word. James never talks about how great art gets made.$batch07$), ($batch07$D$batch07$, $batch07$James says this: people forget all but the greatest past art. Rachel never addresses it.$batch07$), ($batch07$E$batch07$, $batch07$James explains why people misjudge contemporary art, but James never says quality can be judged *only* for past art. Rachel doesn't touch this either.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT118-S1-Q10$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
